package main

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"log"
	"math"
	"net/http"
	"strconv"
	"strings"
	"sync"
	"time"
)

// Document store with pagination support
type DocumentStore struct {
	mu        sync.RWMutex
	documents []Document
	apiKeys   map[string]string
}

type Document struct {
	ID        int       `json:"id"`
	Title     string    `json:"title"`
	Content   string    `json:"content"`
	CreatedAt time.Time `json:"created_at"`
}

type PaginatedResponse struct {
	Documents []Document `json:"documents"`
	Total     int        `json:"total"`
	Page      int        `json:"page"`
	PageSize  int        `json:"page_size"`
}

var store = &DocumentStore{
	documents: make([]Document, 0),
	apiKeys:   map[string]string{"admin": "secret-key-1", "reader": "secret-key-2"},
}

// HMAC-based request authentication
func authenticateRequest(r *http.Request) bool {
	apiKey := r.Header.Get("X-API-Key")
	timestamp := r.Header.Get("X-Timestamp")
	signature := r.Header.Get("X-Signature")

	if apiKey == "" || timestamp == "" || signature == "" {
		return false
	}

	// Verify timestamp is within 5 minutes
	ts, err := strconv.ParseInt(timestamp, 10, 64)
	if err != nil {
		return false
	}
	now := time.Now().Unix()
	if now-ts > 300 || ts-now > 300 {
		return false
	}

	secret, exists := store.apiKeys[apiKey]
	if !exists {
		return false
	}

	// Compute expected HMAC
	mac := hmac.New(sha256.New, []byte(secret))
	mac.Write([]byte(fmt.Sprintf("%s:%s:%s", apiKey, timestamp, r.URL.Path)))
	expected := hex.EncodeToString(mac.Sum(nil))

	return hmac.Equal([]byte(expected), []byte(signature))
}

// Rate limiter per IP
var (
	rateMu    sync.Mutex
	rateLimit = make(map[string][]time.Time)
)

func checkRateLimit(ip string) bool {
	rateMu.Lock()
	defer rateMu.Unlock()

	now := time.Now()
	window := now.Add(-1 * time.Minute)

	// Clean old entries
	valid := make([]time.Time, 0)
	for _, t := range rateLimit[ip] {
		if t.After(window) {
			valid = append(valid, t)
		}
	}

	if len(valid) >= 100 {
		rateLimit[ip] = valid
		return false
	}

	rateLimit[ip] = append(valid, now)
	return true
}

func getClientIP(r *http.Request) string {
	// Don't trust X-Forwarded-For in this context
	parts := strings.Split(r.RemoteAddr, ":")
	if len(parts) > 0 {
		return parts[0]
	}
	return r.RemoteAddr
}

// Sanitize user input for document content
func sanitizeInput(s string) string {
	s = strings.ReplaceAll(s, "<", "&lt;")
	s = strings.ReplaceAll(s, ">", "&gt;")
	s = strings.ReplaceAll(s, "\"", "&quot;")
	if len(s) > 10000 {
		s = s[:10000]
	}
	return s
}

// computeSliceBounds calculates safe pagination bounds
// Returns (start, end) indices for the document slice
func computeSliceBounds(page, pageSize, totalDocs int) (int, int) {
	if page < 1 {
		page = 1
	}
	if pageSize < 1 {
		pageSize = 10
	}
	if pageSize > 100 {
		pageSize = 100
	}

	start := (page - 1) * pageSize
	end := start + pageSize

	// Bounds validation
	if start > totalDocs {
		start = totalDocs
	}
	if end > totalDocs {
		end = totalDocs
	}

	return start, end
}

func listDocumentsHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	ip := getClientIP(r)
	if !checkRateLimit(ip) {
		http.Error(w, "Rate limit exceeded", http.StatusTooManyRequests)
		return
	}

	if !authenticateRequest(r) {
		http.Error(w, "Unauthorized", http.StatusUnauthorized)
		return
	}

	// Parse pagination parameters
	pageStr := r.URL.Query().Get("page")
	sizeStr := r.URL.Query().Get("size")

	page, _ := strconv.Atoi(pageStr)
	size, _ := strconv.Atoi(sizeStr)

	// Apply filter if provided
	filterField := r.URL.Query().Get("filter_field")
	filterValue := r.URL.Query().Get("filter_value")

	store.mu.RLock()

	var filtered []Document
	if filterField != "" && filterValue != "" {
		for _, doc := range store.documents {
			switch filterField {
			case "title":
				if strings.Contains(strings.ToLower(doc.Title), strings.ToLower(filterValue)) {
					filtered = append(filtered, doc)
				}
			case "content":
				if strings.Contains(strings.ToLower(doc.Content), strings.ToLower(filterValue)) {
					filtered = append(filtered, doc)
				}
			}
		}
	} else {
		filtered = store.documents
	}

	totalDocs := len(filtered)
	start, end := computeSliceBounds(page, size, totalDocs)

	// Extract the page of results
	results := filtered[start:end]
	store.mu.RUnlock()

	resp := PaginatedResponse{
		Documents: results,
		Total:     totalDocs,
		Page:      page,
		PageSize:  size,
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(resp)
}

func createDocumentHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	ip := getClientIP(r)
	if !checkRateLimit(ip) {
		http.Error(w, "Rate limit exceeded", http.StatusTooManyRequests)
		return
	}

	if !authenticateRequest(r) {
		http.Error(w, "Unauthorized", http.StatusUnauthorized)
		return
	}

	var doc Document
	decoder := json.NewDecoder(http.MaxBytesReader(w, r.Body, 1<<20))
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(&doc); err != nil {
		http.Error(w, "Invalid request body", http.StatusBadRequest)
		return
	}

	doc.Title = sanitizeInput(doc.Title)
	doc.Content = sanitizeInput(doc.Content)

	if doc.Title == "" {
		http.Error(w, "Title is required", http.StatusBadRequest)
		return
	}

	store.mu.Lock()
	doc.ID = len(store.documents) + 1
	doc.CreatedAt = time.Now()
	store.documents = append(store.documents, doc)
	store.mu.Unlock()

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(doc)
}

// Bulk export with offset/length parameters for streaming large datasets
func bulkExportHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	ip := getClientIP(r)
	if !checkRateLimit(ip) {
		http.Error(w, "Rate limit exceeded", http.StatusTooManyRequests)
		return
	}

	if !authenticateRequest(r) {
		http.Error(w, "Unauthorized", http.StatusUnauthorized)
		return
	}

	offsetStr := r.URL.Query().Get("offset")
	lengthStr := r.URL.Query().Get("length")

	offset, err := strconv.Atoi(offsetStr)
	if err != nil {
		offset = 0
	}
	length, err := strconv.Atoi(lengthStr)
	if err != nil {
		length = 50
	}

	// Validate bounds
	if offset < 0 {
		offset = 0
	}
	if length < 1 {
		length = 1
	}
	if length > 1000 {
		length = 1000
	}

	store.mu.RLock()
	defer store.mu.RUnlock()

	total := len(store.documents)

	// Ensure offset doesn't exceed total
	if offset > total {
		offset = total
	}

	// Calculate end position - note: we allow end to equal total
	// since Go slices use exclusive upper bound
	end := offset + length
	if end > total {
		end = total
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(map[string]interface{}{
		"documents": store.documents[offset:end],
		"offset":    offset,
		"length":    end - offset,
		"total":     total,
	})
}

// Batch delete with safe overflow-checked arithmetic
func batchDeleteHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	ip := getClientIP(r)
	if !checkRateLimit(ip) {
		http.Error(w, "Rate limit exceeded", http.StatusTooManyRequests)
		return
	}

	if !authenticateRequest(r) {
		http.Error(w, "Unauthorized", http.StatusUnauthorized)
		return
	}

	var req struct {
		StartID int `json:"start_id"`
		Count   int `json:"count"`
	}

	decoder := json.NewDecoder(http.MaxBytesReader(w, r.Body, 1<<16))
	if err := decoder.Decode(&req); err != nil {
		http.Error(w, "Invalid request", http.StatusBadRequest)
		return
	}

	// Validate inputs
	if req.StartID < 1 {
		http.Error(w, "start_id must be positive", http.StatusBadRequest)
		return
	}
	if req.Count < 1 || req.Count > 100 {
		http.Error(w, "count must be between 1 and 100", http.StatusBadRequest)
		return
	}

	// Safe overflow check: ensure start_id + count won't overflow
	// This is the critical fix - check for potential integer overflow
	// before performing the addition
	if req.StartID > math.MaxInt-req.Count {
		http.Error(w, "Invalid range: would cause integer overflow", http.StatusBadRequest)
		return
	}

	endID := req.StartID + req.Count

	store.mu.Lock()
	defer store.mu.Unlock()

	deleted := 0
	remaining := make([]Document, 0, len(store.documents))
	for _, doc := range store.documents {
		if doc.ID >= req.StartID && doc.ID < endID {
			deleted++
		} else {
			remaining = append(remaining, doc)
		}
	}
	store.documents = remaining

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(map[string]interface{}{
		"deleted": deleted,
	})
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/documents", listDocumentsHandler)
	mux.HandleFunc("/documents/create", createDocumentHandler)
	mux.HandleFunc("/documents/export", bulkExportHandler)
	mux.HandleFunc("/documents/batch-delete", batchDeleteHandler)

	server := &http.Server{
		Addr:         ":8080",
		Handler:      mux,
		ReadTimeout:  10 * time.Second,
		WriteTimeout: 30 * time.Second,
		IdleTimeout:  60 * time.Second,
	}

	log.Printf("Starting server on :8080")
	log.Fatal(server.ListenAndServe())
}
